def max_expression_value(s):
    n = len(s)
    digits = [int(s[i]) for i in range(n) if i % 2 == 0]
    signs = [s[i] for i in range(n) if i % 2 == 1]

    max_value = float('-inf')

    # Calculate all possible positions to add brackets
    for i in range(len(signs)):
        for j in range(i + 1, len(signs)):
            # Calculate expression value with brackets at positions (i, j)
            current_value = calculate_with_brackets(digits, signs, i, j)
            max_value = max(max_value, current_value)

    return max_value

def calculate_with_brackets(digits, signs, i, j):
    # First part: calculate (x1 to xj)
    first_part = digits[0]
    for k in range(1, j + 1):
        if k - 1 == i:
            first_part = perform_operation(first_part, digits[k], '+')
        else:
            first_part = perform_operation(first_part, digits[k], signs[k - 1])

    # Second part: calculate (xj+1 to xn)
    second_part = digits[j + 1]
    for k in range(j + 2, len(digits)):
        second_part = perform_operation(second_part, digits[k], signs[k - 1])

    # Result: first part * second part
    return first_part * second_part

def perform_operation(a, b, op):
    if op == '+':
        return a + b
    elif op == '*':
        return a * b

