def evaluate_expression(expr):
    """
    Evaluate the given mathematical expression with proper order of operations.
    """
    def apply_operations(operators, values):
        right = values.pop()
        left = values.pop()
        op = operators.pop()
        if op == '+':
            values.append(left + right)
        elif op == '*':
            values.append(left * right)

    def precedence(op):
        if op == '+':
            return 1
        if op == '*':
            return 2
        return 0

    def evaluate(expr):
        operators = []
        values = []
        i = 0
        while i < len(expr):
            if expr[i] == '(':
                operators.append(expr[i])
            elif expr[i].isdigit():
                values.append(int(expr[i]))
            elif expr[i] == ')':
                while operators and operators[-1] != '(':
                    apply_operations(operators, values)
                operators.pop()  # pop '('
            else:
                while (operators and precedence(operators[-1]) >= precedence(expr[i])):
                    apply_operations(operators, values)
                operators.append(expr[i])
            i += 1
        while operators:
            apply_operations(operators, values)
        return values[0]

    return evaluate(expr)

